import{_ as t,o as a,c as s,a5 as i}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"SDK des widgets, passerelle et frontières des incrustations","description":"","frontmatter":{"title":"SDK des widgets, passerelle et frontières des incrustations","docId":"developer.overlays","translationKey":"developer.overlays","locale":"fr","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"99d3351859ddb3a3304133f062f68b8e3130416947fc40433dc9c6bffaf85f6a","translationRevision":"2211002bf9220b3092af524f9f29298a14f76cb68647bab383e335489e8692b8","order":170},"headers":[],"relativePath":"fr/developer/overlays.md","filePath":"fr/developer/overlays.md","lastUpdated":1794611623000}'),n={name:"fr/developer/overlays.md"};function l(r,e,o,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="widget-sdk-gateway-and-overlay-boundaries" tabindex="-1">SDK des widgets, passerelle et frontières des incrustations <a class="header-anchor" href="#widget-sdk-gateway-and-overlay-boundaries" aria-label="Permalink to &quot;SDK des widgets, passerelle et frontières des incrustations {#widget-sdk-gateway-and-overlay-boundaries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Créer un widget partageant son rendu entre l’aperçu local et la sortie OBS. Utilisez la chaîne Vue installée et comprenez les <a href="./events.html">événements</a>. L’aperçu local ne nécessite ni passerelle ni identifiant de compte. La sortie de widgets en direct nécessite le plugin event-gateway installé séparément et son identifiant limité aux widgets.</p><h2 id="add-a-template" tabindex="-1">Ajouter un modèle <a class="header-anchor" href="#add-a-template" aria-label="Permalink to &quot;Ajouter un modèle {#add-a-template}&quot;">​</a></h2><ol><li>Définissez un moteur de rendu dans <code>WidgetStage</code> ; dimensionnez-le relativement à son parent plutôt qu’à la fenêtre du navigateur.</li><li>Utilisez <code>defineWidget</code> de <code>src/widgets/sdk/template.ts</code>. Fournissez son schéma, de nouvelles enveloppes d’exemple et une fabrique <code>create(search, clock)</code>.</li><li>Renvoyez un contrôleur implémentant <code>handleEnvelope</code>, <code>clear</code> et <code>dispose</code>, ainsi que le rendu. Utilisez l’horloge fournie pour que les aperçus puissent maintenir les échantillons et les tests avancer le temps.</li><li>Enregistrez-le dans <code>sdk/templates.ts</code>, puis ajoutez l’entrée autonome, la configuration de compilation, la liste de routes autorisées de la passerelle et l’entrée d’empaquetage. L’enregistrement seul n’expose pas d’URL publique.</li><li>Utilisez le même <code>WidgetHost.vue</code> dans l’éditeur et le bundle autonome ; n’intégrez pas le HTML de la passerelle pour un aperçu local.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span></code></pre></div><p>Gardez les jetons de texte, valeurs de conception par défaut et champs modifiables dans le schéma du modèle. Les conceptions se sérialisent en JSON et les URL de widgets copiées portent un instantané validé ; un enregistrement ultérieur exige de copier une URL actualisée dans OBS.</p><h2 id="gateway-protocol" tabindex="-1">Protocole de passerelle <a class="header-anchor" href="#gateway-protocol" aria-label="Permalink to &quot;Protocole de passerelle {#gateway-protocol}&quot;">​</a></h2><p><code>src/widgets/shared/gateway-client.ts</code> possède l’authentification, les abonnements, le battement de vie, la reconnexion et le signalement de lacunes. Les widgets consomment des enveloppes métier canoniques, pas TikTok directement. Le point de terminaison des widgets est <code>/ws/widgets</code> ; il diffère de l’interface complète du client externe de passerelle. Analysez les enveloppes avec l’analyseur partagé et préservez les frontières des identifiants plutôt que de passer un jeton complet de passerelle par la WebView principale.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les aperçus locaux intégrés et le SDK des widgets sont implémentés. L’édition d’incrustation Cloud et le code source <code>cloud-overlay</code> existent, mais la validation OBS réelle, la couverture des illustrations/sources en direct et l’application de paquets gardent des limites. Overlay Changes est un travail ultérieur non fusionné. Rankings reste masqué dans la navigation normale malgré l’existence du code du widget de classement.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Pour un aperçu local vide, examinez la durée de vie du contrôleur, les valeurs par défaut du schéma et le dimensionnement de la scène avant d’affaiblir la politique d’origine. Pour la sortie en direct, examinez la santé de la passerelle, l’identifiant de widget et les lacunes explicites. Un test Chromium sans interface ne prouve pas la validation d’une source navigateur OBS. Le <a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/widgets/sdk" target="_blank" rel="noreferrer">SDK des widgets</a> et les tests du protocole partagé sont les références actuelles d’implémentation.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>La suite unitaire utilise des fixtures ; Chromium avec gateway réel exige assets construits et dépôt externe via <code>TIKTOOLS_PLUGINS_REPO</code>. Sans source, elle est ignorée : signalez ce skip. Lancez <code>bun x --no-install playwright test --config src/widgets/playwright.gateway.config.ts</code> pour cette frontière. Vérifiez ensuite OBS réel, clé widget, livraison et reprise LIVE ; Chromium headless ne prouve pas l’acceptation OBS/native.</p>`,15)])])}const g=t(n,[["render",l]]);export{h as __pageData,g as default};
